val job = launch {
    try {
        while (isActive) {                       // safe point
            ensureActive()
            process(receive())
        }
    } finally {
        close()                                  // runs on cancellation too
    }
}

job.cancel()                                     // request, not termination

val job = launch(Dispatchers.IO) {
    runInterruptible {
        try {
            blockingRead()            // interruptible JVM call
        } catch (e: InterruptedException) {
            throw e                   // becomes CancellationException once unwound
        }
    }
}
job.cancel()                          // cancels and interrupts the blocked thread

